package com.lexiscan.analysis; import com.fasterxml.jackson.databind.*; import com.lexiscan.document.*; import com.lexiscan.report.ReportService; import com.lexiscan.user.User; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/documents/{id}") public class AnalysisController {final DocumentService docs;final AnalysisService analysis;final ObjectMapper json;final ReportService reports;public AnalysisController(DocumentService d,AnalysisService a,ObjectMapper j,ReportService r){docs=d;analysis=a;json=j;reports=r;} record Response(String summary,int overallRiskScore,String overallRiskLevel,Object entities,List<Clause> clauses){} @GetMapping("/analysis") Response get(@PathVariable UUID id,@AuthenticationPrincipal User u)throws Exception{var d=docs.mine(id,u);var r=analysis.result(d);return new Response(r.getSummary(),r.getOverallRiskScore(),r.getOverallRiskLevel(),json.readValue(r.getKeyEntities(),Object.class),analysis.clauses(d));}@GetMapping("/clauses") List<Clause> clauses(@PathVariable UUID id,@AuthenticationPrincipal User u,@RequestParam(required=false) String category,@RequestParam(required=false) String riskLevel){return analysis.clauses(docs.mine(id,u)).stream().filter(c->category==null||c.getCategory().equalsIgnoreCase(category)).filter(c->riskLevel==null||c.getRiskLevel().equalsIgnoreCase(riskLevel)).toList();}@GetMapping("/report") ResponseEntity<byte[]> report(@PathVariable UUID id,@AuthenticationPrincipal User u)throws Exception{var d=docs.mine(id,u);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=lexiscan-report.pdf").contentType(MediaType.APPLICATION_PDF).body(reports.generate(d,analysis.result(d),analysis.clauses(d)));}}
